#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.18945410000000001, -0.35459722000000005, 0.040308689999999994], 'basis': [[0.0, 0.8111688070713652, 0.5848120778800814], [-0.9958995038295806, -0.052905871621614003, 0.07338356096533198], [0.09046644832199005, -0.5824140581943191, 0.8078426124844054]], 'axis': [0.5848120778800814, 0.07338356096533198, 0.8078426124844054], 'zmin': -0.011738882730200994, 'zmax': 0.015815518796375553, 'profiles': [{'outer': [[-0.049070397038614155, 0.006314035281709018], [-0.04774961287733928, 0.013402793702009102], [-0.04536367630028462, 0.018740945698547846], [-0.04019722453414948, 0.02794897337136479], [-0.03832609502644666, 0.03173339772551096], [-0.037711320281495944, 0.03276069668716924], [-0.03728221285845035, 0.034091820456205534], [-0.03516126002066578, 0.0371355637849367], [-0.030364229188581563, 0.03556660421642209], [-0.02542676018628146, 0.036113161890084615], [-0.014481124024944685, 0.03522222837300923], [-0.007584255364103222, 0.03363140373146743], [-0.00170612296160723, 0.031499942844543945], [0.005045130810963547, 0.028337563523930062], [0.01020079927686194, 0.025475806977228278], [0.01612047839574981, 0.022378383085997954], [0.025911927024925844, 0.018482201620385635], [0.034528848942115796, 0.01537438840214169], [0.04041732210773284, 0.012760394613088512], [0.042958685969356744, 0.010867640115022363], [0.043946194303859126, 0.009887641950748972], [0.043842195601692294, 0.00823314866353737], [0.04219448434679537, 0.0071054673903989535], [0.039065775434967344, 0.0071123603187458195], [0.03297981306106154, 0.008396010639038854], [0.024061381262843788, 0.01056619974445186], [0.016327985034068317, 0.012248550967144646], [0.01633384086837094, 0.01091447695631221], [0.028484243219694498, 0.005128361814693441], [0.038805833336239215, -0.00019120520090794356], [0.04558295820868589, -0.0035638941433998035], [0.04857653507462546, -0.006097410572377083], [0.04930929178869798, -0.007945138264234533], [0.04847769926960722, -0.009275453112295287], [0.04675732177550301, -0.010167895633290966], [0.04273978805268134, -0.009816246561477658], [0.035775483710164195, -0.007419970149680759], [0.026108637446765868, -0.0038122654138558155], [0.0149048946494508, -0.00018115203223294859], [0.014544800534783794, -0.0021488501790083553], [0.027246675800392157, -0.009485464403556361], [0.037641000721191704, -0.015554202423778586], [0.044397323958707276, -0.019350233592555402], [0.048425167419747214, -0.023585481351068225], [0.04801448417107995, -0.025771642426500433], [0.04602375705940796, -0.026638142509998828], [0.041819206107020376, -0.025777926817721637], [0.03487050972063617, -0.023297392951518302], [0.023337928556900027, -0.018345551337553247], [0.010085121032651448, -0.013641077763494536], [0.008458269114073566, -0.015325043891571976], [0.01715304600010285, -0.0223768431978296], [0.02466809253635279, -0.02832747185754121], [0.02979249529501017, -0.031963072568938405], [0.03270808778583778, -0.034690159056624724], [0.0333761545221253, -0.036898384819842964], [0.034386767429958394, -0.037854049017441965], [0.03287946742553896, -0.03984475329175298], [0.03146566788623641, -0.03978471549224162], [0.028295365663541242, -0.039180942366653704], [0.02535890478206404, -0.03757400372742592], [0.019881106958701333, -0.03398287425322258], [0.010271444096895137, -0.02846463950046145], [-0.0005802924561843611, -0.021951071670341202], [-0.0057567616523493325, -0.01914012578772939], [-0.010268006205567858, -0.016948921640258335], [-0.016873761246320382, -0.014463386674307169], [-0.017570326409627208, -0.015156220136284563], [-0.011947255801157384, -0.02470579716472129], [-0.00986461891049504, -0.02788179638566458], [-0.0075767627922510095, -0.03090974240392395], [-0.007192018303842769, -0.031957484030821326], [-0.00608526352286534, -0.03514316125034739], [-0.006293103453270126, -0.03585126474239463], [-0.006235975700483756, -0.03729006619459179], [-0.008346218752245236, -0.03836377694584143], [-0.010419943811915073, -0.03748806582372965], [-0.013268012138029429, -0.03561471895864787], [-0.01957728822562456, -0.029540625424608107], [-0.028812611822026695, -0.021136542636059432], [-0.031224096165866022, -0.01845323710389638], [-0.03729436505784801, -0.012059618592817574], [-0.04385295107752628, -0.001491851565354676], [-0.045562251946077194, 0.0022083054538625095], [-0.046482233027830014, 0.003468437540445218]], 'holes': []}], 'simplify_tolerance': 1.9675937765462428e-05, 'sketch_entity_count': 124}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
